'use client';

import { useEffect, useRef, useState } from 'react';
import { cn } from '@/lib/utils';
import { useRaf } from '@/hooks/use-raf';
import { useReducedMotion } from '@/hooks/use-reduced-motion';
import { useResizeObserver } from '@/hooks/use-resize-observer';
import { useSmoothPointer } from '@/hooks/use-smooth-pointer';
import { useVisibility } from '@/hooks/use-visibility';
import { hasWebGL, loseContext, pixelRatio } from '@/lib/webgl';
import {
  DOMAIN_WARPED_FBM_FRAG,
  DOMAIN_WARPED_FBM_VERT,
} from '@/components/motion/shaders/domain-warped-fbm';

/* ==========================================================================
   Domain-Warped FBM Fog
   --------------------------------------------------------------------------
   Raw WebGL2 on a single fullscreen triangle. Two octaves of value noise are
   sampled twice to build an offset vector, and that offset is fed back into a
   third sample — Iñigo Quílez's domain warp. It is the difference between
   blobs that fade in and out, and a field that looks like it is flowing.

   The whole image lives in a narrow, low band of the value range. That is the
   point: it is a backdrop for type, not a picture.
   ========================================================================== */

export interface DomainWarpedFbmProps {
  /**
   * Noise frequency. Below 1.0 the features are larger than the screen, which
   * is what makes this fog rather than static.
   */
  scale?: number;
  /** How far the first two fbm samples displace the third. */
  warp?: number;
  /** Peak brightness added above the base colour. */
  gain?: number;
  /** Multiplier on the (already very slow) drift. */
  speed?: number;
  /** Base colour, linear 0..1 RGB. Read straight into the shader. */
  base?: readonly [number, number, number];
  /** Colour of the lit part of the fog, linear 0..1 RGB. */
  tint?: readonly [number, number, number];
  maxDpr?: number;
  className?: string;
}

// #region critical
const TRIANGLE = new Float32Array([-1, -1, 3, -1, -1, 3]);
const SCALE = 0.7;
const WARP = 0.4;
const GAIN = 0.22;
const BASE: readonly [number, number, number] = [0.03, 0.032, 0.042];
const TINT: readonly [number, number, number] = [0.86, 0.9, 1];

interface Gpu {
  gl: WebGL2RenderingContext;
  program: WebGLProgram;
  vao: WebGLVertexArrayObject;
  buffer: WebGLBuffer;
  locations: Map<string, WebGLUniformLocation | null>;
}

/* A local 60-line bootstrap rather than three.js or ogl. This component draws
   three vertices; a framework would be 100x its own weight in dependency. */
function build(gl: WebGL2RenderingContext, vertSrc: string, fragSrc: string): Gpu | null {
  const compile = (type: number, src: string): WebGLShader | null => {
    const shader = gl.createShader(type);
    if (!shader) return null;
    gl.shaderSource(shader, src);
    gl.compileShader(shader);
    if (gl.getShaderParameter(shader, gl.COMPILE_STATUS)) return shader;
    console.error('[domain-warped-fbm]', gl.getShaderInfoLog(shader));
    gl.deleteShader(shader);
    return null;
  };

  const vert = compile(gl.VERTEX_SHADER, vertSrc);
  const frag = compile(gl.FRAGMENT_SHADER, fragSrc);
  const program = gl.createProgram();
  const vao = gl.createVertexArray();
  const buffer = gl.createBuffer();
  if (!vert || !frag || !program || !vao || !buffer) return null;

  gl.attachShader(program, vert);
  gl.attachShader(program, frag);
  gl.linkProgram(program);
  gl.deleteShader(vert);
  gl.deleteShader(frag);
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    console.error('[domain-warped-fbm]', gl.getProgramInfoLog(program));
    gl.deleteProgram(program);
    return null;
  }

  gl.bindVertexArray(vao);
  gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
  gl.bufferData(gl.ARRAY_BUFFER, TRIANGLE, gl.STATIC_DRAW);
  const attrib = gl.getAttribLocation(program, 'a_pos');
  if (attrib >= 0) {
    gl.enableVertexAttribArray(attrib);
    gl.vertexAttribPointer(attrib, 2, gl.FLOAT, false, 0, 0);
  }
  gl.bindVertexArray(null);

  return { gl, program, vao, buffer, locations: new Map() };
}

function loc(gpu: Gpu, name: string): WebGLUniformLocation | null {
  const cached = gpu.locations.get(name);
  if (cached !== undefined) return cached;
  const found = gpu.gl.getUniformLocation(gpu.program, name);
  gpu.locations.set(name, found);
  return found;
}

export function DomainWarpedFbm({
  scale = SCALE,
  warp = WARP,
  gain = GAIN,
  speed = 1,
  base = BASE,
  tint = TINT,
  maxDpr = 2,
  className,
}: DomainWarpedFbmProps) {
  const host = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const gpuRef = useRef<Gpu | null>(null);

  const { width, height } = useResizeObserver(host);
  const reduced = useReducedMotion();
  const visible = useVisibility();
  // Heavy smoothing: the pointer drives a warp offset, and an unsmoothed
  // pointer makes the whole field snap between frames rather than drift.
  const pointer = useSmoothPointer({ target: host, smoothing: 0.02 });
  const [supported, setSupported] = useState(true);

  const paramsRef = useRef({ scale, warp, gain, speed, base, tint });
  paramsRef.current = { scale, warp, gain, speed, base, tint };

  const drawRef = useRef<(elapsed: number) => void>(() => {});
  drawRef.current = (elapsed: number) => {
    const gpu = gpuRef.current;
    if (!gpu) return;
    const { gl } = gpu;
    const params = paramsRef.current;
    const p = pointer.current;

    gl.useProgram(gpu.program);
    gl.uniform2f(
      loc(gpu, 'u_resolution'),
      gl.drawingBufferWidth,
      gl.drawingBufferHeight,
    );
    gl.uniform1f(loc(gpu, 'u_time'), elapsed * params.speed);
    gl.uniform2f(loc(gpu, 'u_pointer'), p.nx, 1 - p.ny);
    gl.uniform1f(loc(gpu, 'u_scale'), params.scale);
    gl.uniform1f(loc(gpu, 'u_warp'), params.warp);
    gl.uniform1f(loc(gpu, 'u_gain'), params.gain);
    gl.uniform3f(loc(gpu, 'u_base'), params.base[0], params.base[1], params.base[2]);
    gl.uniform3f(loc(gpu, 'u_tint'), params.tint[0], params.tint[1], params.tint[2]);

    gl.bindVertexArray(gpu.vao);
    gl.drawArrays(gl.TRIANGLES, 0, 3);
    gl.bindVertexArray(null);
  };

  useEffect(() => {
    const el = host.current;
    if (!el) return;
    if (!hasWebGL()) {
      setSupported(false);
      return;
    }

    /* The canvas is created here, not rendered by React, because the cleanup
       below hands the context back through `WEBGL_lose_context` — and
       `getContext` on an element that has been through that returns the SAME
       dead context, not a new one. Keeping React's element across the cycle
       therefore made the loss permanent. This is not a dev-only StrictMode
       concern: the preview host hides components with `<Activity mode="hidden">`,
       which unmounts effects while keeping the DOM, so scrolling a preview out
       of view and back is exactly that cycle. */
    const canvas = document.createElement('canvas');
    canvas.className = 'block h-full w-full';

    const gl = canvas.getContext('webgl2', {
      antialias: false,
      alpha: false,
      depth: false,
      stencil: false,
      powerPreference: 'high-performance',
    });
    if (!gl) {
      setSupported(false);
      return;
    }

    const gpu = build(gl, DOMAIN_WARPED_FBM_VERT, DOMAIN_WARPED_FBM_FRAG);
    if (!gpu) {
      loseContext(gl);
      setSupported(false);
      return;
    }
    el.append(canvas);
    canvasRef.current = canvas;
    gpuRef.current = gpu;
    setSupported(true);

    // Ignore the loss and the browser keeps handing us a dead context: the
    // canvas is then blank permanently, with no fallback underneath it. The
    // `preventDefault` is the part that leaves a restore on the table.
    const onLost = (event: Event): void => {
      event.preventDefault();
      // Detached as well: the fallback renders as a sibling in normal flow,
      // so a canvas left in place would cover it.
      canvas.remove();
      setSupported(false);
    };
    canvas.addEventListener('webglcontextlost', onLost);

    return () => {
      canvas.removeEventListener('webglcontextlost', onLost);
      gpuRef.current = null;
      canvasRef.current = null;
      gl.deleteVertexArray(gpu.vao);
      gl.deleteBuffer(gpu.buffer);
      gl.deleteProgram(gpu.program);
      loseContext(gl);
      canvas.remove();
    };
  }, []);

  useEffect(() => {
    const canvas = canvasRef.current;
    const gpu = gpuRef.current;
    if (!canvas || !gpu || width === 0 || height === 0) return;

    const dpr = pixelRatio(maxDpr);
    const w = Math.max(1, Math.round(width * dpr));
    const h = Math.max(1, Math.round(height * dpr));
    if (canvas.width !== w || canvas.height !== h) {
      canvas.width = w;
      canvas.height = h;
    }
    gpu.gl.viewport(0, 0, w, h);
    // One frame here covers both the first paint and the reduced-motion path.
    drawRef.current(reduced ? 12 : 0);
  }, [width, height, maxDpr, supported, reduced]);

  const running = supported && visible && !reduced && width > 0 && height > 0;
  useRaf((_dt, elapsed) => drawRef.current(elapsed), running);
  // #endregion critical

  return (
    <div ref={host} className={cn('relative h-full w-full overflow-hidden', className)}>
      {/* The canvas is appended by the effect above, not rendered here. */}
      {!supported && (
        <div
          aria-hidden
          className="h-full w-full bg-bg"
          style={{
            backgroundImage:
              'radial-gradient(120% 90% at 30% 25%, var(--k-surface) 0%, transparent 55%), radial-gradient(90% 80% at 75% 70%, var(--k-bg-subtle) 0%, transparent 60%)',
          }}
        />
      )}

    </div>
  );
}

/* ==========================================================================
   Domain-Warped FBM Fog — GLSL ES 3.00
   --------------------------------------------------------------------------
   `#version 300 es` must be the first token in the file, so the literal opens
   flush against the backtick.
   ========================================================================== */

export const DOMAIN_WARPED_FBM_VERT = `#version 300 es
in vec2 a_pos;
out vec2 v_uv;

void main() {
  v_uv = a_pos * 0.5 + 0.5;
  gl_Position = vec4(a_pos, 0.0, 1.0);
}
`;

export const DOMAIN_WARPED_FBM_FRAG = `#version 300 es
precision highp float;

in vec2 v_uv;
out vec4 fragColor;

uniform vec2  u_resolution;
uniform float u_time;
uniform vec2  u_pointer;   /* 0..1, y up, already smoothed on the CPU */
uniform float u_scale;     /* < 1.0 makes features LARGER than the screen */
uniform float u_warp;      /* how far the first two fbm samples push the third */
uniform float u_gain;      /* peak brightness above the base colour */
uniform vec3  u_base;
uniform vec3  u_tint;

/* --------------------------------------------------------------------------
   Value noise. Cheaper than simplex and indistinguishable once the result has
   been through a smoothstep, which is exactly what happens below.

   The hash folds its input into 0..1 with fract() BEFORE the sin(). Feeding
   sin() a large argument is the classic way this hash falls apart: past a few
   thousand radians the fractional part of the angle is quantised, the noise
   develops visible repeating bands, and it breaks on mobile GPUs long before
   it breaks on the desktop it was written on.
   -------------------------------------------------------------------------- */
float hash13(vec3 p) {
  p = fract(p * 0.3183099 + 0.1);
  return fract(sin(dot(p, vec3(127.1, 311.7, 74.7))) * 43758.5453123);
}

float vnoise(vec3 p) {
  vec3 i = floor(p);
  vec3 f = fract(p);
  /* Hermite fade. Plain linear interpolation leaves visible creases along the
     lattice because the first derivative is discontinuous at the cell walls. */
  vec3 u = f * f * (3.0 - 2.0 * f);

  float n000 = hash13(i);
  float n100 = hash13(i + vec3(1.0, 0.0, 0.0));
  float n010 = hash13(i + vec3(0.0, 1.0, 0.0));
  float n110 = hash13(i + vec3(1.0, 1.0, 0.0));
  float n001 = hash13(i + vec3(0.0, 0.0, 1.0));
  float n101 = hash13(i + vec3(1.0, 0.0, 1.0));
  float n011 = hash13(i + vec3(0.0, 1.0, 1.0));
  float n111 = hash13(i + vec3(1.0, 1.0, 1.0));

  float x00 = mix(n000, n100, u.x);
  float x10 = mix(n010, n110, u.x);
  float x01 = mix(n001, n101, u.x);
  float x11 = mix(n011, n111, u.x);

  return mix(mix(x00, x10, u.y), mix(x01, x11, u.y), u.z) * 2.0 - 1.0;
}

/* Two octaves, amplitude 0.6 then 0.3, lacunarity 1.93. Standard fbm runs
   four to six; two is enough because the result is immediately crushed by
   smoothstep(0.25, 0.85, n) and the extra detail is thrown away. Halving the
   octave count halves the cost of the shader, since fbm IS the shader. */
float fbm(vec3 p) {
  float sum = 0.0;
  float amp = 0.6;
  for (int i = 0; i < 2; i++) {
    sum += amp * vnoise(p);
    p *= 1.93;
    amp *= 0.5;
  }
  return sum;
}

void main() {
  float aspect = u_resolution.x / max(u_resolution.y, 1.0);

  /* Correct BOTH the sample space and the pointer. Correcting only the sample
     space leaves the cursor glow as an ellipse on a wide screen. */
  vec2 p = v_uv;
  p.x *= aspect;
  vec2 m = u_pointer;
  m.x *= aspect;

  float t = u_time * 0.03;
  vec2 sp = p * u_scale;

  /* Domain warp: two decorrelated fbm samples become an offset fed into a
     third. The vec2(2.3, 1.1) shift on the second channel is what decorrelates
     it — without it both channels return the same value and the "warp"
     degenerates into a pure diagonal translation.

     The pointer enters three times with different weights and a sign flip
     between the two warp channels, so they shear against each other. Three
     weak influences read as "the fog responds to you"; one strong influence
     reads as "the fog is stuck to the cursor". */
  vec2 q = vec2(
    fbm(vec3(sp + m * 0.20, t)),
    fbm(vec3(sp + vec2(2.3, 1.1) - m * 0.20, t))
  );
  float n = fbm(vec3(sp + q * u_warp + m * 0.12, t * 0.8)) * 0.5 + 0.5;

  float shade = smoothstep(0.25, 0.85, n);
  float lift = (u_pointer.y - 0.5) * 0.03;

  vec3 col = u_base + u_tint * (u_gain * shade + lift);

  /* Reversed smoothstep arguments make a FALLING ramp: 1 at the pointer, 0 at
     distance 0.85. Cheaper and clearer than 1.0 - smoothstep(0.0, 0.85, d). */
  float d = distance(p, m);
  col += u_tint * smoothstep(0.85, 0.0, d) * (u_gain * 0.55);

  /* Multiply, do not subtract: scaling the whole result keeps the cursor glow
     inside the vignette instead of letting it punch through at the corners. */
  float vig = smoothstep(1.25, 0.5, distance(v_uv, vec2(0.5)));
  col *= mix(0.85, 1.0, vig);

  fragColor = vec4(col, 1.0);
}
`;
